//! The `shipping_tier` suite: one test per scenario in `features/suites/shipping_tier.feature`.
//!
//! Generated by prism-code from the app's spec. The proofs are checked by the
//! Lean kernel when `just vv` runs `prismpm verify` on `app/`. What these tests
//! hold fixed is the claim each proof is about: the condition no request may
//! meet, and the theorem that states none does. A weakened condition would
//! still verify, and would no longer be the claim its row makes.

use std::path::PathBuf;

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .ancestors()
        .nth(2)
        .expect("crates/conformance is two below the root")
        .to_path_buf()
}

/// The body of the top-level declaration named `name`, up to its closing brace.
fn declaration<'a>(model: &'a str, name: &str) -> &'a str {
    let start = model
        .find(&format!("\n  name: {name},\n"))
        .unwrap_or_else(|| panic!("{name} is not declared"));
    let end = model[start..]
        .find("\n}\n")
        .unwrap_or_else(|| panic!("{name} is not closed"));
    &model[start..start + end]
}

/// The condition no request may meet, and the theorem that says none does.
fn pinned(breaks: &str, condition: &str, theorem: &str) {
    let path = root().join("app/src/ShippingTierProofs.lex.tex");
    let model = std::fs::read_to_string(path).expect("the proofs module");
    let found = declaration(&model, breaks);
    assert!(
        found.contains(condition),
        "the condition of {breaks} changed:\n{found}"
    );
    let holds = declaration(&model, theorem);
    let statement = format!("statement: (({breaks} request) = false),");
    assert!(
        holds.contains(&statement),
        "{theorem} must state that no request meets {breaks}:\n{holds}"
    );
}

/// `ST-01`: The app always answers freight when weight is above 30000
#[test]
fn shipping_tier_st_01() {
    pinned(
        "breaksInv001",
        "body: (((((1 <=? (project request weight)) && (1 <=? (project request distance))) && (1 <=? (project request items))) && (30000 <? (project request weight))) && (not ((ShippingTier::judge request) =? (ShippingTier::answerFreight))))",
        "inv001Holds",
    );
}

/// `ST-02`: The app never answers express when weight is above 30000
#[test]
fn shipping_tier_st_02() {
    pinned(
        "breaksInv002",
        "body: (((((1 <=? (project request weight)) && (1 <=? (project request distance))) && (1 <=? (project request items))) && (30000 <? (project request weight))) && ((ShippingTier::judge request) =? (ShippingTier::answerExpress)))",
        "inv002Holds",
    );
}

/// `ST-03`: The app never answers express when membership is none and weight is at most 30000 and items is at most 50
#[test]
fn shipping_tier_st_03() {
    pinned(
        "breaksInv003",
        "body: (((((((1 <=? (project request weight)) && (1 <=? (project request distance))) && (1 <=? (project request items))) && ((project request membership) =? (ShippingTier::membershipNone))) && ((project request weight) <=? 30000)) && ((project request items) <=? 50)) && ((ShippingTier::judge request) =? (ShippingTier::answerExpress)))",
        "inv003Holds",
    );
}
